    written: [
      { q: "'हिंदुस्तान की कहानी' के रचयिता कौन हैं और पाठ उसका कौन-सा अध्याय है?", a: "जवाहरलाल नेहरू; पाठ उसका पाँचवाँ अध्याय है।", marks: 1 },
      { q: "नेहरू को बच्चे किस नाम से पुकारते थे?", a: "चाचा नेहरू।", marks: 1 },
      { q: "नेहरू ने किसानों की समस्याओं के किन कारणों की ओर ध्यान दिलाया?", a: "1. गरीबी और कर्ज़दारी, जिसमें पूँजीपतियों का शिकंजा था।\n2. ज़मींदार, महाजन, कड़ा लगान और सूद, पुलिस का ज़ुल्म।\n3. ये सब विदेशी सरकार के ढाँचे से जुड़े थे, जिससे छुटकारा सभी को चाहिए था।", marks: 3 },
      { q: "नेहरू ने किसानों से 'भारत माता' के बारे में बातचीत कैसे शुरू की और जाट के उत्तर पर क्या प्रश्न किया?", a: "1. 'भारत माता की जय' के नारे के बाद उन्होंने पूछा कि यह भारत माता कौन है।\n2. लोग चकित होकर एक-दूसरे को देखने लगे; एक जाट ने कहा कि धरती।\n3. नेहरू ने पूछा – कौन-सी धरती? गाँव की, ज़िले की, सूबे की या सारे हिंदुस्तान की?", marks: 3 },
      { q: "पाठ के आधार पर नेहरू के भाषणों की शैली की विशेषताएँ लिखिए।", a: "1. वे श्रोताओं से संवाद करते हुए प्रश्न पूछते और उत्तर तक पहुँचते थे।\n2. उदाहरण किसानों की रोज़मर्रा की समस्याओं से लेते थे।\n3. भाषा सरल, बोलचाल की, उर्दू शब्दों से युक्त और असरदार है।", marks: 3 },
      { q: "नेहरू ने 'भारत माता' का अर्थ किस प्रकार स्पष्ट किया? इस अर्थ का राष्ट्र-निर्माण में क्या महत्त्व है?", a: "1. उन्होंने कहा कि नदी, पहाड़, जंगल, खेत प्रिय हैं, पर असली गिनती देश के लोगों की है।\n2. भारत माता देश के करोड़ों लोग हैं और 'भारत माता की जय' का अर्थ इन लोगों की जय है।\n3. इससे हर नागरिक में देश का अंश होने का गर्व जागता है।\n4. देश की प्रगति का अर्थ आम जनता की प्रगति हो जाता है, जिससे समानता और एकता को बल मिलता है।\n5. देश-प्रेम केवल नारा न रहकर जन-सेवा की भावना बनता है।", marks: 5 },
      { q: "'भारत माता' पाठ में किन आधारों पर देश की एकता सिद्ध की गई है? विस्तार से लिखिए।", a: "1. उत्तर-पश्चिम में खैबर के दर्रे से कन्याकुमारी तक किसानों की परेशानियाँ एक-सी हैं।\n2. ये परेशानियाँ विदेशी सरकार के ढाँचे से जुड़ी हैं, जिससे छुटकारा सबको पाना है।\n3. पुराने महाकाव्यों और पुराणों की कथाओं ने लोगों के मन में पूरे देश की कल्पना बनाई।\n4. चारों कोनों के तीर्थों की यात्राएँ और सिपाहियों के विदेशी अनुभव उन्हें बड़ी दुनिया से जोड़ते हैं।\n5. इस तरह भिन्नताओं के बावजूद हिंदुस्तान एक है।", marks: 5 },
      { q: "निम्नलिखित स्थिति पढ़कर प्रश्नों के उत्तर दीजिए –\nएक विद्यालय में 'हमारा भारत' विषय पर बातचीत हो रही है। एक विद्यार्थी कहता है – 'देश का अर्थ केवल नक्शा और सीमाएँ हैं।' दूसरा कहता है – 'देश वहाँ रहने वाले लोग हैं, जिनके सुख-दुख हम सबको जोड़ते हैं।'\n(i) किसका विचार नेहरू के विचार से मिलता है?\n(ii) नेहरू ने जाट से बातचीत में क्या समझाया?\n(iii) हम देश के प्रति अपना प्रेम कैसे दिखा सकते हैं?", a: "(i) दूसरे विद्यार्थी का।\n(ii) कि भारत माता केवल धरती नहीं, बल्कि इसके करोड़ों लोग हैं और जय उन्हीं की है।\n(iii) आम लोगों के हित में काम करके, एकता और परस्पर सम्मान बनाए रखकर और सबकी भलाई की चिंता करके।", marks: 4, type: "case" }
    ]
