      { q: "कविता में सबसे ख़तरनाक किसे कहा गया है?", options: ["पुलिस की मार", "हमारे सपनों का मर जाना", "मेहनत की लूट", "गद्दारी और लोभ"], answer: 1, explain: "कवि के अनुसार सबसे ख़तरनाक है सपनों का मर जाना और मुर्दा शांति से भर जाना।", level: 1 },
      { q: "कवि ने 'मुर्दा शांति से भर जाना' को ख़तरनाक क्यों माना है?", options: ["क्योंकि इससे शोर होता है", "क्योंकि इसमें तड़प और प्रतिरोध की भावना खत्म हो जाती है", "क्योंकि इसमें लड़ाई होती है", "क्योंकि इससे नींद नहीं आती"], answer: 1, explain: "तड़प का न होना और सब कुछ सहन कर लेना बदलाव की इच्छा को मार देता है।", level: 2 },
      { q: "'वह घड़ी सबसे ख़तरनाक होती है जो कलाई पर चलती हुई भी निगाह में रुकी होती है' – इसका आशय है –", options: ["घड़ी ख़राब है", "समय का महत्त्व नहीं है", "घड़ी बहुत महँगी है", "समय बीतता है पर जीवन में जड़ता और ठहराव है"], answer: 3, explain: "यह जीवन के अर्थहीन दुहराव और ठहराव का प्रतीक है।", level: 2 },
      { q: "कवि ने कौन-सी आँख ख़तरनाक बताई है?", options: ["जो सब कुछ देखकर भी जमी बर्फ़ बनी रहे", "जो रोती हो", "जो बहुत बड़ी हो", "जो सपने देखती हो"], answer: 0, explain: "जमी बर्फ़ जैसी आँख संवेदना और प्यार से दुनिया को देखना भूल चुकी है।", level: 2 },
      { q: "कविता में 'गीत' को ख़तरनाक कब बताया गया है?", options: ["जब वह धीमी आवाज़ में हो", "जब वह बहुत लंबा हो", "जब वह मरसिया पढ़ता है और आतंकित लोगों के दरवाज़ों पर गुंडे की तरह अकड़ता है", "जब वह लोकगीत हो"], answer: 2, explain: "ऐसा गीत भय और शोक फैलाता है, आशा नहीं देता।", level: 2 },
      { q: "'घर से निकलना काम पर और काम से लौटकर घर आना' को ख़तरनाक कहने का कारण है –", options: ["काम करना बुरा है", "काम कठिन है", "घर दूर है", "लक्ष्यहीन, यांत्रिक दुहराव में जीवन के सपनों का खो जाना"], answer: 3, explain: "कवि रोज़मर्रा के यांत्रिक क्रम में सपनों और संघर्ष की चेतना के खो जाने से चिंतित है।", level: 3 },
      { q: "कविता की शुरुआत और अंत में एक ही पंक्तियों को दोहराने का क्या प्रभाव है?", options: ["कविता लंबी हो जाती है", "वह बात ज़ोर से रेखांकित होती है कि बाहरी अत्याचार से अधिक ख़तरनाक भीतर की संवेदनहीनता है", "लय बिगड़ जाती है", "कविता कठिन हो जाती है"], answer: 1, explain: "पुनरावृत्ति से कविता का केंद्रीय विचार असरदार बनता है।", level: 3 },
      { q: "कवि के अनुसार 'आत्मा का सूरज डूब जाना' किस स्थिति का सूचक है?", options: ["सूर्यास्त का", "बुढ़ापे का", "चेतना, सपनों और संवेदना के पूरी तरह खत्म हो जाने का", "रात के आने का"], answer: 2, explain: "आत्मा का सूरज डूबना जीवन-चेतना के अंत का प्रतीक है।", level: 3 },
      { q: "पाश अपनी कविताओं में जनसामान्य की घटनाओं पर कैसे प्रतिक्रिया करते हैं?", options: ["गहरे जुड़ाव और संपृक्तता के साथ, जिसमें व्यथा, निराशा और गुस्सा है", "'आउटसाइडर' की तरह दूर से", "केवल व्यंग्य से", "केवल उपदेश से"], answer: 0, explain: "पाठ के परिचय के अनुसार उनकी कविताओं में गहरी संपृक्तता दिखती है।", level: 3 }
